import json
from pathlib import Path

import pytest
from hypothesis import given, strategies as st

import tox
from tox.session.cmd.schema import _process_type
from tox.tox_env.python.pip.req_file import PythonDeps

jsonschema = pytest.importorskip("jsonschema")

SCHEMA_FILE = Path(tox.__file__).parent / "tox.schema.json"


def _validator(subschema):
    full = json.loads(SCHEMA_FILE.read_text(encoding="utf-8"))
    wrapped = {**subschema, "definitions": full.get("definitions", {})}
    return jsonschema.Draft7Validator(wrapped)


def _generated_deps():
    return _process_type(PythonDeps)


def _published_deps():
    full = json.loads(SCHEMA_FILE.read_text(encoding="utf-8"))
    return full["properties"]["env_run_base"]["properties"]["deps"]


@pytest.fixture(params=["generated", "published"])
def deps_validator(request):
    sub = _generated_deps() if request.param == "generated" else _published_deps()
    return _validator(sub)


def test_deps_accepts_a_string(deps_validator):
    """The deps schema accepts a single string."""
    assert deps_validator.is_valid("pytest>=7")


def test_deps_accepts_array_of_strings(deps_validator):
    """The deps schema accepts an array of strings such as requirements and requirements-file arguments."""
    assert deps_validator.is_valid(["pytest>=7", "-r requirements.txt", "-c constraints.txt"])


def test_deps_accepts_empty_array(deps_validator):
    """The deps schema accepts an empty array."""
    assert deps_validator.is_valid([])


def test_deps_rejects_non_string_non_array(deps_validator):
    """The deps schema rejects values that are neither a string nor an array, such as numbers, booleans and objects."""
    assert not deps_validator.is_valid(5)
    assert not deps_validator.is_valid(True)
    assert not deps_validator.is_valid({"a": "b"})


def test_deps_rejects_array_with_non_string_items(deps_validator):
    """The deps schema rejects arrays containing non-string items such as numbers."""
    assert not deps_validator.is_valid([1, 2])


def test_published_schema_deps_is_not_string_only():
    """The published tox.schema.json deps property is no longer string-only."""
    assert _published_deps() != {
        "type": "string",
        "description": _published_deps().get("description"),
    }


@given(st.lists(st.text(), max_size=8))
def test_any_array_of_strings_is_valid_deps(items):
    """Every array of strings is valid for deps in both generated and published schemas."""
    assert _validator(_generated_deps()).is_valid(items)
    assert _validator(_published_deps()).is_valid(items)


@given(st.text())
def test_any_string_is_valid_deps(value):
    """Every string is valid for deps in both generated and published schemas."""
    assert _validator(_generated_deps()).is_valid(value)
    assert _validator(_published_deps()).is_valid(value)


@given(st.one_of(st.integers(), st.floats(allow_nan=False), st.booleans()))
def test_any_scalar_non_string_is_invalid_deps(value):
    """No number or boolean is valid for deps."""
    assert not _validator(_generated_deps()).is_valid(value)
    assert not _validator(_published_deps()).is_valid(value)

